import os
import re
from contextlib import contextmanager
from functools import partial
from inspect import currentframe
from logging import Logger
from subprocess import check_output
from SSHLibrary.abstractclient import SSHClientException
from six import string_types
from ta_egate_cmd_parser import ta_egate_cmd_parser

from ta_logcollector.logger import get_net_logger
from ta_logcollector.settings import SERVER_HOST
from ta_logcollector.task import Task
from ta_logcollector.utils.common import execute_in_parallel, get_fsm_sw_version
from ta_logcollector.utils.emss import get_emss_connection
from ta_logcollector.utils.internal import save_result_data

logger = Logger("LC")


def start():
    # type: () -> None
    """
    Does nothing.
    Just for unifying with all plugins.
    """
    logger.info("inside {} before start".format(__name__))
    logger.info("inside {} after start".format(__name__))


def _get_requested_data(**kwargs):
    allowed_requests = {
        "bts_sw": partial(_get_fsm_sw_directly, "enb"),
        "ue_sim_sw": partial(_get_ue_sim_sw),
        "bts_info": partial(_get_emss_bts_info),
        "ute_ver": partial(_get_ute_ver),
        "wts_ver": partial(_get_wts_ver),
    }
    for key in kwargs:
        if key in allowed_requests.keys() and kwargs[key]:
            yield allowed_requests[key], key


def _get_ue_sim_sw(**kwargs):
    uesim_conf = kwargs["ue_sim_sw"]
    ue_sim_sw = []
    if "iphy" in uesim_conf:
        ue_sim_sw.append(_get_iphy_sw())
    if "cus" in uesim_conf:
        ue_sim_sw.append(_get_cus_sw())
    return "\n".join(ue_sim_sw)


def _get_iphy_sw():
    return _get_fsm_sw_directly("iphy")


def _get_cus_sw():
    return _get_fsm_sw_directly("cus")


def _collect_data(requested_data, **kwargs):
    try:
        return requested_data(**kwargs)
    except Exception as exc:
        logger.error(
            "Error occured for {} - {} with args: {} kwargs: {}. {}: {}".format(
                requested_data,
                requested_data.func.__name__,
                requested_data.args,
                requested_data.keywords,
                type(exc).__name__,
                exc,
            ),
            exc_info=True,
        )


def _get_emss_bts_info(**kwargs):
    # type: (dict) -> dict
    """
    Executes "bts_info" command on emss and returns parsed result.
    :return: list of bts_info for each enb from each emss
    """
    bts_info = {}
    emss_connections_data = kwargs.get("bts_info")
    for emss, emss_id in get_emss_connection(logger, emss_connections_data, 4000):
        bts_info["emss_{}".format(emss_id)] = emss.run_emssim_command("bts_info")
    return bts_info


def _get_fsm_sw_directly(fsm_type, timeout=60, **kwargs):
    # type: (str, int, dict) -> str
    """
    Gets fsm SW using ute_fsmaccess library.
    :param fsm_type: iphy or enb
    :param timeout: timeout in seconds
    :return: FSM SW with it's type
    """
    logger.debug("fsm_type = {} bts_sw = {}".format(fsm_type, kwargs.get("bts_sw")))
    try:
        fsm_sw = get_fsm_sw_version(logger, fsm_type, timeout)
    except SSHClientException as exc:
        logger.error("SSH Connection to {} timed out. {}: {}".format(fsm_type, type(exc).__name__, exc), exc_info=True)
        fsm_sw = ""
    return "{} SW: {}".format(fsm_type.upper(), fsm_sw)


def _get_wts_ver(**kwargs):
    # type: (dict) -> str
    """
    Get WTS version currently running.

    :return: WTS version
    """
    logger.debug("_get_wts_ver: {}".format(kwargs.get("wts_ver")))
    ver = "unknown"
    try:
        info_cmd = ta_egate_cmd_parser().get_command("info")
        info_cmd_output = info_cmd().execute_and_parse()
        matched_ver = re.search(r"\s\((WTS_.*)\)", info_cmd_output, re.MULTILINE)
        if matched_ver:
            ver = matched_ver.group(1)
    except Exception as err:
        logger.error(err, exc_info=True)
    return "WTS version: {}".format(ver)


def _get_ute_ver(**kwargs):
    # type: (dict) -> str
    """
    Get UTE package version form dpkg util.

    :return: UTE package version
    """
    logger.debug("_get_ute_ver: {}".format(kwargs.get("ute_ver")))
    ver = "unknown"
    output = check_output(["dpkg-query -s ute"], shell=True)
    matched_ver = re.search(r"Version:\s(.*)", output if isinstance(output, string_types) else output.decode())
    if matched_ver:
        ver = matched_ver.group(1)
    return "UTE package: {}".format(ver)


def _save_results(name, log_path, future):
    # type: (str, str, Future) -> None
    result = future.result()
    logger.debug("{} finished".format(name))
    save_result_data(result, log_path)


def stop(log_path, **kwargs):
    # type: (str, dict) -> None
    """
    Collects requested data upon finalising logs collection

    :param log_path: path to directory with logs
    """
    logger.info("inside {} before stop".format(__name__))
    log_path = os.path.join(log_path, "summary_{}.txt".format(SERVER_HOST))
    execute_in_parallel(
        [
            Task(_collect_data, requested_data, fn_callback=partial(_save_results, name, log_path), **kwargs)
            for requested_data, name in _get_requested_data(**kwargs)
        ]
    )
    logger.info("inside {} after stop".format(__name__))


@contextmanager
def final_report(log_host, log_port, **kwargs):
    # type: (str, int, dict) -> None
    """
    TBD, just for py.test check

    :param log_host: IP address of logger host
    :param log_port: port of logger host
    """
    global logger
    logger = get_net_logger(log_host, log_port, "{}_{}".format(currentframe().f_code.co_name, SERVER_HOST))
    log_dir = kwargs.pop("log_dir")
    try:
        start()
        yield
    finally:
        stop(log_dir, **kwargs)
